(function() {
    'use strict';

    class CharacterAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Character Under Pressure`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Northwind Mobility, CAD).
            this.START_BALANCE = 30;     // character-balance index, headroom kept
            this.START_QUALITY = 25;     // decision-quality score
            this.START_TRUST = 40;       // stakeholder trust
            this.START_RISK = 35;        // deadline / safety risk (LOWER is better)
            this.BUDGET_CAP = 6.0;       // CA$6.0M remediation + mitigation envelope
            this.REMEDIATION = 4.2;      // CA$4.2M foam change + re-tooling
            this.WIN_QUALITY = 70;       // sound-decision threshold
            this.WIN_BALANCE = 65;       // balanced-character threshold

            // Concept truths.
            this.TRUE_FRAME = `character`;
            this.TRUE_OVERPLAY = `drive`;
            this.TRUE_UNDERPLAY = `courage`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    balance: this.START_BALANCE,
                    quality: this.START_QUALITY,
                    trust: this.START_TRUST,
                    risk: this.START_RISK,
                    budgetUsed: 0,
                    concealed: false,
                    oneDimDominated: false,
                    punishedCourage: false,
                    balanceHistory: [this.START_BALANCE],
                    qualityHistory: [this.START_QUALITY],
                    trustHistory: [this.START_TRUST],
                    riskHistory: [this.START_RISK],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Deliberately a plausible-but-mediocre default mix — a click-through must NOT auto-win.
                state.decisions = {
                    frame: `character`,
                    overplay: `humility`,
                    underplay: `drive`,
                    judgment: 50,
                    action: `fix`,
                    courage: 30,
                    temperance: 25,
                    account: 25,
                    collab: 20,
                    tradeoff: `none`,
                    board: `cave`,
                    quality: `neutral`,
                    retailer: `bluff`,
                    humility: 50,
                    judge: `outcome`,
                    disclose: `minimal`,
                    capacity: `drive`,
                    practice: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const ov = document.getElementById(`overplayInput`);
                const un = document.getElementById(`underplayInput`);
                const jd = document.getElementById(`judgmentInput`);
                if (fr) decisions.frame = fr.value;
                if (ov) decisions.overplay = ov.value;
                if (un) decisions.underplay = un.value;
                if (jd) decisions.judgment = parseInt(jd.value, 10);
                if (!Number.isFinite(decisions.judgment) || decisions.judgment < 0 || decisions.judgment > 100) {
                    warn(`warn_judgment_range`); return false;
                }
            } else if (round === 2) {
                const ac = document.getElementById(`actionInput`);
                const tr = document.getElementById(`tradeoffInput`);
                if (ac) decisions.action = ac.value;
                if (tr) decisions.tradeoff = tr.value;
                const c = document.getElementById(`courageInput`);
                const t = document.getElementById(`temperanceInput`);
                const a = document.getElementById(`accountInput`);
                const co = document.getElementById(`collabInput`);
                if (c) decisions.courage = parseFloat(c.value);
                if (t) decisions.temperance = parseFloat(t.value);
                if (a) decisions.account = parseFloat(a.value);
                if (co) decisions.collab = parseFloat(co.value);
                const parts = [decisions.courage, decisions.temperance, decisions.account, decisions.collab];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_weight_negative`); return false;
                }
                const total = Math.round(decisions.courage + decisions.temperance + decisions.account + decisions.collab);
                if (total !== 100) {
                    warn(`warn_weight_total`); return false;
                }
                if (parts.some((v) => v > 45)) {
                    warn(`warn_weight_dominate`); return false;
                }
            } else if (round === 3) {
                const bo = document.getElementById(`boardInput`);
                const qu = document.getElementById(`qualityInput`);
                const re = document.getElementById(`retailerInput`);
                const hu = document.getElementById(`humilityInput`);
                if (bo) decisions.board = bo.value;
                if (qu) decisions.quality = qu.value;
                if (re) decisions.retailer = re.value;
                if (hu) decisions.humility = parseInt(hu.value, 10);
                if (!Number.isFinite(decisions.humility) || decisions.humility < 0 || decisions.humility > 100) {
                    warn(`warn_humility_range`); return false;
                }
            } else if (round === 4) {
                const ju = document.getElementById(`judgeInput`);
                const di = document.getElementById(`discloseInput`);
                const ca = document.getElementById(`capacityInput`);
                const pr = document.getElementById(`practiceInput`);
                if (ju) decisions.judge = ju.value;
                if (di) decisions.disclose = di.value;
                if (ca) decisions.capacity = ca.value;
                if (pr) decisions.practice = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.practice) || decisions.practice < 0 || decisions.practice > 100) {
                    warn(`warn_practice_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let balanceDelta = 0, qualityDelta = 0, trustDelta = 0, riskDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Frame the dilemma through the character lens (Common Error 1: legality as the standard).
                switch (d.frame) {
                    case `character`: qualityDelta += 12; balanceDelta += 7; coachKey = `coach_r1_frame_character`; break;
                    case `financial`: qualityDelta -= 6; riskDelta += 6; coachKey = `coach_r1_frame_financial`; break;
                    case `legal`: qualityDelta -= 12; riskDelta += 12; coachKey = `coach_r1_frame_legal`; break;
                    case `political`: qualityDelta -= 10; trustDelta -= 6; coachKey = `coach_r1_frame_political`; break;
                }

                // Name the over-played dimension under board pressure — Drive.
                if (d.overplay === this.TRUE_OVERPLAY) { balanceDelta += 8; qualityDelta += 3; }
                else { balanceDelta -= 6; coachKey = (d.frame === this.TRUE_FRAME) ? `coach_r1_overplay_wrong` : coachKey; }

                // Name the under-played dimension — Courage & Accountability.
                if (d.underplay === this.TRUE_UNDERPLAY) {
                    balanceDelta += 8; qualityDelta += 3;
                    if (d.frame === this.TRUE_FRAME && d.overplay === this.TRUE_OVERPLAY) coachKey = `coach_r1_diag_sharp`;
                } else { balanceDelta -= 6; }

                // Judgment integrating explicitly (Common Error 2: hunch not character).
                if (d.judgment >= 60) { qualityDelta += 6; balanceDelta += 3; }
                else if (d.judgment <= 25) { qualityDelta -= 8; coachKey = `coach_r1_lowjudgment`; }

                summaryKey = (d.frame === this.TRUE_FRAME && d.overplay === this.TRUE_OVERPLAY && d.underplay === this.TRUE_UNDERPLAY)
                    ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Decide & justify with four dimensions in balance (Common Errors 1 & 3).
                const c = d.courage, t = d.temperance, a = d.account, co = d.collab;
                const vals = [c, t, a, co];
                const maxV = Math.max.apply(null, vals);
                const minV = Math.min.apply(null, vals);
                const spread = maxV - minV;

                // The action itself.
                switch (d.action) {
                    case `fix`:
                        qualityDelta += 10; trustDelta += 6; riskDelta -= 22; spend += this.REMEDIATION;
                        coachKey = `coach_r2_fix`; break;
                    case `phased`:
                        // A genuine structured alternative — sound if balanced, but more execution risk than the clean fix.
                        qualityDelta += 8; trustDelta += 8; riskDelta -= 14; spend += 2.6;
                        coachKey = `coach_r2_phased`; break;
                    case `ship`:
                        // Legality-as-standard (Common Error 1): margin protected, real risk carried into the field.
                        qualityDelta -= 14; trustDelta -= 4; riskDelta += 26; coachKey = `coach_r2_ship`; break;
                    case `conceal`:
                        // Integrity breach (decision tree): converts a risk call into an indefensible ethical breach.
                        qualityDelta -= 22; trustDelta -= 12; riskDelta += 32; ds.concealed = true;
                        coachKey = `coach_r2_conceal`; break;
                }

                // Character balance: tight spread across the four dimensions rewards equilibrium;
                // one dimension dominating (high spread) is the vice (Common Error 3).
                if (spread <= 15) { balanceDelta += 12; qualityDelta += 3; coachKey = (d.action === `fix` || d.action === `phased`) ? `coach_r2_balanced` : coachKey; }
                else if (spread <= 25) { balanceDelta += 5; }
                else { balanceDelta -= 12; ds.oneDimDominated = true; coachKey = `coach_r2_dominate`; }

                // Courage and Accountability must be genuinely present (not zeroed out under pressure).
                if (c >= 20 && a >= 20) { balanceDelta += 5; qualityDelta += 3; }
                else { balanceDelta -= 6; qualityDelta -= 4; }

                // Trade-off must be named honestly. "No trade-off" is a fantasy; sacrificing safety is the wrong sacrifice.
                switch (d.tradeoff) {
                    case `margin`: qualityDelta += 7; trustDelta += 4; break;
                    case `none`: qualityDelta -= 10; coachKey = `coach_r2_tradenone`; break;
                    case `safety`: qualityDelta -= 14; riskDelta += 10; coachKey = `coach_r2_tradesafety`; break;
                }

                const soundAction = (d.action === `fix` || d.action === `phased`);
                summaryKey = (soundAction && spread <= 15 && d.tradeoff === `margin`) ? `sum_r2_good`
                    : (d.action === `conceal` ? `sum_r2_breach` : `sum_r2_weak`);
            } else if (round === 3) {
                // Hold the line under live confrontation (Common Errors 3 & 4; Humility check).
                // Board chair.
                switch (d.board) {
                    case `defend`: qualityDelta += 12; trustDelta += 8; balanceDelta += 4; coachKey = `coach_r3_defend`; break;
                    case `cave`: qualityDelta -= 12; trustDelta -= 6; riskDelta += 16; coachKey = `coach_r3_cave`; break;
                    case `war`: balanceDelta -= 14; trustDelta -= 10; ds.oneDimDominated = true; coachKey = `coach_r3_war`; break;
                }

                // Head of Quality / whistle-raiser (Common Error 4: punishing courage).
                switch (d.quality) {
                    case `back`: trustDelta += 14; balanceDelta += 8; qualityDelta += 4; coachKey = (d.board === `defend`) ? `coach_r3_back` : coachKey; break;
                    case `neutral`: trustDelta -= 2; balanceDelta -= 2; break;
                    case `sideline`: trustDelta -= 16; balanceDelta -= 8; ds.punishedCourage = true; coachKey = `coach_r3_sideline`; break;
                }

                // Retailer — protect relationship without compromising the standard (Integrity).
                switch (d.retailer) {
                    case `honest`: trustDelta += 8; qualityDelta += 4; break;
                    case `bluff`: trustDelta -= 6; riskDelta += 6; coachKey = `coach_r3_bluff`; break;
                    case `cave`: trustDelta -= 4; riskDelta += 18; qualityDelta -= 8; coachKey = `coach_r3_retailcave`; break;
                }

                // Humility check: revising on evidence is virtue; ego-rigidity or total reversal both cost.
                if (d.humility >= 45 && d.humility <= 80) { balanceDelta += 8; qualityDelta += 4; }
                else if (d.humility < 25) { balanceDelta -= 6; coachKey = `coach_r3_norevise`; }
                else if (d.humility > 90) { balanceDelta -= 4; coachKey = `coach_r3_overrevise`; }

                summaryKey = (d.board === `defend` && d.quality === `back` && d.retailer === `honest`) ? `sum_r3_good`
                    : (d.quality === `sideline` ? `sum_r3_punished` : `sum_r3_weak`);
            } else if (round === 4) {
                // Outcome, decision quality vs outcome, and building character capacity (Common Error 5).
                switch (d.judge) {
                    case `separate`: qualityDelta += 16; balanceDelta += 6; coachKey = `coach_r4_separate`; break;
                    case `outcome`: qualityDelta -= 14; coachKey = `coach_r4_outcome`; break;
                    case `luck`: qualityDelta -= 8; balanceDelta -= 6; coachKey = `coach_r4_luck`; break;
                }

                // Disclosure / Integrity (decision tree: concealment).
                switch (d.disclose) {
                    case `transparent`: trustDelta += 12; riskDelta -= 12; qualityDelta += 4; coachKey = (d.judge === `separate`) ? `coach_r4_transparent` : coachKey; break;
                    case `minimal`: trustDelta -= 4; riskDelta += 4; coachKey = `coach_r4_minimal`; break;
                    case `deny`: trustDelta -= 14; riskDelta += 18; qualityDelta -= 8; ds.concealed = true; coachKey = `coach_r4_deny`; break;
                }

                // Building character capacity for the next collision.
                switch (d.capacity) {
                    case `courage`: balanceDelta += 12; qualityDelta += 6; break;
                    case `drive`: balanceDelta -= 6; coachKey = `coach_r4_capdrive`; break;
                    case `none`: balanceDelta -= 10; coachKey = `coach_r4_capnone`; break;
                }

                // Commitment to an embedded practice nudges balance & quality.
                balanceDelta += Math.round((d.practice - 60) / 8);
                qualityDelta += Math.round((d.practice - 60) / 10);

                summaryKey = (d.judge === `separate` && d.disclose === `transparent` && d.capacity === `courage`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (CAD millions). Cap can bind on a fix + heavy mitigation.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            if (ds.budgetUsed > this.BUDGET_CAP) {
                // Over-spend forces a crude saving that re-opens risk — the cap genuinely binds.
                riskDelta += 8;
                qualityDelta -= 4;
                ds.budgetUsed = this.BUDGET_CAP;
                coachKey = `coach_overbudget`;
            }

            ds.balance = Math.max(0, Math.min(100, ds.balance + balanceDelta));
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualityDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.risk = Math.max(0, Math.min(100, ds.risk + riskDelta));

            ds.balanceHistory.push(Math.round(ds.balance));
            ds.qualityHistory.push(Math.round(ds.quality));
            ds.trustHistory.push(Math.round(ds.trust));
            ds.riskHistory.push(Math.round(ds.risk));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore),
            // so the instructor score card and the per-round score trend populate. Same formula as getPerformanceSummary.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                balance: Math.round(ds.balance),
                balanceDelta: Math.round(balanceDelta),
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualityDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                risk: Math.round(ds.risk),
                riskDelta: Math.round(riskDelta),
                budgetUsed: ds.budgetUsed,
                concealed: ds.concealed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

