                total = Math.round(total);
                if (wReadout) wReadout.textContent = total;
                const bar = document.querySelector(`.charactersim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100 || over) ? `#c0392b` : ``;
            };
            wIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

