        _composite(ds) {
            const balance = Math.round(ds.balance);
            const quality = Math.round(ds.quality);
            const trust = Math.round(ds.trust);
            const risk = Math.round(ds.risk);
            const composite = Math.round(quality * 0.30 + balance * 0.30 + trust * 0.22 + (100 - risk) * 0.18);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.soundDecision
                ? `<span class="charactersim-cm-badge charactersim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="charactersim-cm-badge charactersim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.breach) failBadges += ` <span class="charactersim-cm-badge charactersim-cm-fail">` + T(`cm_breach`) + `</span>`;
            if (s.oneDimDominated) failBadges += ` <span class="charactersim-cm-badge charactersim-cm-fail">` + T(`cm_dominate`) + `</span>`;
            if (s.punishedCourage) failBadges += ` <span class="charactersim-cm-badge charactersim-cm-fail">` + T(`cm_punished`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="charactersim-cm-metric"><span class="charactersim-cm-mv">` + Math.round(s.balance || 0) + `</span><span class="charactersim-cm-ml">` + T(`cm_m_balance`) + `</span></div>`
                + `<div class="charactersim-cm-metric"><span class="charactersim-cm-mv">` + Math.round(s.quality || 0) + `</span><span class="charactersim-cm-ml">` + T(`cm_m_quality`) + `</span></div>`
                + `<div class="charactersim-cm-metric"><span class="charactersim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="charactersim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="charactersim-cm-metric charactersim-cm-metric-risk"><span class="charactersim-cm-mv">` + Math.round(s.risk || 0) + `</span><span class="charactersim-cm-ml">` + T(`cm_m_risk`) + `</span></div>`;
            return ``
                + `<div class="charactersim-completion">`
                +   `<div class="charactersim-cm-head">`
                +     `<div class="charactersim-cm-score">` + score + `<span class="charactersim-cm-score-max">/100</span></div>`
                +     `<div class="charactersim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="charactersim-cm-metrics">` + metrics + `</div>`
                +   `<div class="charactersim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="charactersim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const balance = Math.round(ds.balance);
            const quality = Math.round(ds.quality);
            const trust = Math.round(ds.trust);
            const risk = Math.round(ds.risk);

            const soundDecision = quality >= this.WIN_QUALITY && balance >= this.WIN_BALANCE;
            const breach = ds.concealed;
            // Composite folds risk in inverted (low risk is good). Single source of truth: _composite(ds).
            const composite = this._composite(ds);

            let performanceKey = `grade_reactive`;
            if (breach) performanceKey = `grade_breach`;
            else if (soundDecision && trust >= 60 && composite >= 72) performanceKey = `grade_charled`;
            else if (soundDecision) performanceKey = `grade_thintrust`;
            else if (quality >= this.WIN_QUALITY && balance < this.WIN_BALANCE) performanceKey = `grade_dominated`;
            else if (composite >= 55) performanceKey = `grade_improving`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (breach) insights.push(window.mySimulation.t(`insight_breach`));
            else if (soundDecision && trust >= 60) insights.push(window.mySimulation.t(`insight_charled`));
            else if (soundDecision) insights.push(window.mySimulation.t(`insight_thintrust`));
            else insights.push(window.mySimulation.t(`insight_reactive`));

            if (ds.oneDimDominated) insights.push(window.mySimulation.t(`insight_dominate`));
            if (ds.punishedCourage) insights.push(window.mySimulation.t(`insight_punished`));
            if (risk >= 55) insights.push(window.mySimulation.t(`insight_risk`));
            if (quality >= this.WIN_QUALITY && trust < 50) insights.push(window.mySimulation.t(`insight_qualnotoutcome`));
            if (soundDecision && trust >= 60 && risk <= 30) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                balance: balance,
                quality: quality,
                trust: trust,
                risk: risk,
                soundDecision: soundDecision,
                breach: breach,
                oneDimDominated: ds.oneDimDominated,
                punishedCourage: ds.punishedCourage,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.concealed) return window.mySimulation.t(`hint_breach`);
            if (ds.oneDimDominated && state.currentPeriod >= 2) return window.mySimulation.t(`hint_dominate`);
            if (ds.punishedCourage) return window.mySimulation.t(`hint_punished`);
            if (ds.risk >= 55) return window.mySimulation.t(`hint_risk`);
            if (state.currentPeriod >= 3 && ds.quality < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.quality >= this.WIN_QUALITY && ds.balance >= this.WIN_BALANCE && ds.trust >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

